/* Parcelamento do líquido aprovado, retenção liberada e cobranças avulsas. */
(function(root){'use strict';const D=root.Obras,$=s=>document.querySelector(s),h=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),money=v=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format(v),id=()=> 'PAR-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,10);let api,pending=false;
function generate(total,count,first){if(!Number.isInteger(count)||count<1||count>120)throw Error('Informe de 1 a 120 parcelas.');let cents=Math.round(total*100),base=Math.floor(cents/count),extra=cents%count;if(!base)throw Error('O valor é pequeno demais para esta quantidade de parcelas.');if(!/^\d{4}-\d{2}-\d{2}$/.test(first)||D.date(first)?.toLocaleDateString('sv-SE')!==first)throw Error('Informe o primeiro vencimento válido.');return Array.from({length:count},(_,i)=>({id:id(),amount:(base+(i<extra?1:0))/100,due:D.addMonths(first,i)}))}
function generateTerms(total,count,first,entryAmount=0,entryDue=''){if(!Number.isFinite(entryAmount)||entryAmount<0||Math.abs(entryAmount*100-Math.round(entryAmount*100))>.000001||Math.round(entryAmount*100)>Math.round(total*100))throw Error('A entrada deve estar entre zero e o valor total, com até dois decimais.');if(!entryAmount)return generate(total,count,first);if(!/^\d{4}-\d{2}-\d{2}$/.test(entryDue)||D.date(entryDue)?.toLocaleDateString('sv-SE')!==entryDue)throw Error('Informe o vencimento válido da entrada.');let entry={id:id(),kind:'Entrada',amount:entryAmount,due:entryDue},balance=(Math.round(total*100)-Math.round(entryAmount*100))/100;return [entry,...(balance?generate(balance,count,first):[])]}
function open(sourceId,type){let snapshot=D.clone(api.getState()),row=D.receivableTotals(snapshot).find(r=>r.sourceId===sourceId&&r.type===type);if(!row)throw Error('Conta a receber não encontrada.');let plan=D.clone(D.receivablePlan(snapshot,row)||[{id:id(),amount:row.amount,due:row.due||D.today()}]),receipts=snapshot.receipts.filter(r=>row.manual?r.receivableId===sourceId:!r.receivableId&&r.project===row.project&&r.number===row.number&&(r.receiptType==='Retenção')===(type==='Retenção')),lockedIds=new Set(receipts.filter(r=>r.installmentId).map(r=>r.installmentId));$('#readerTitle').textContent='Parcelar conta a receber';$('#readerContent').innerHTML='<div class="reader-page receivable-plan"><h3>'+h(row.number)+' · '+h(row.client)+'</h3><p>Total a distribuir: <strong>'+money(row.amount)+'</strong>. Cada parcela terá seu próprio vencimento e recebimento.</p><div class="wf-form"><label>Número de parcelas<input id="receivablePlanCount" type="number" min="1" max="120" value="'+plan.length+'"></label><label>Primeiro vencimento<input id="receivablePlanFirst" type="date" value="'+h(plan[0].due)+'"></label></div><button type="button" class="button secondary" id="receivablePlanGenerate">Gerar parcelas mensais</button><p class="section-note">Depois de gerar, ajuste os valores e as datas na grade. Recebimentos anteriores são preservados; parcelas com recebimentos vinculados mantêm sua identificação.</p><div class="table-wrap" id="receivablePlanRows"></div><button type="button" class="button secondary" id="receivablePlanAdd">+ Parcela</button><p id="receivablePlanTotal" aria-live="polite"></p><p id="receivablePlanError" class="red-text" role="alert"></p><button type="button" class="button primary" id="receivablePlanSave">Salvar parcelamento</button></div>';$('#reader').showModal();function showError(e){$('#receivablePlanError').textContent=e.message||String(e)}function totals(){let total=plan.reduce((n,p)=>n+Math.round(Number(p.amount||0)*100),0)/100;$('#receivablePlanTotal').textContent='Soma das parcelas: '+money(total)+' · Diferença: '+money(Math.round((row.amount-total)*100)/100)}function paint(){$('#receivablePlanRows').innerHTML='<table><thead><tr><th>Parcela</th><th>Valor (R$)</th><th>Vencimento</th><th></th></tr></thead><tbody>'+plan.map((p,i)=>'<tr><td>'+(p.kind==='Entrada'?'Entrada':plan.slice(0,i+1).filter(x=>x.kind!=='Entrada').length+' / '+plan.filter(x=>x.kind!=='Entrada').length)+'</td><td><input aria-label="Valor da parcela '+(i+1)+'" data-rp-value="'+i+'" inputmode="decimal" value="'+Number(p.amount).toFixed(2).replace('.',',')+'"></td><td><input aria-label="Vencimento da parcela '+(i+1)+'" data-rp-date="'+i+'" type="date" value="'+h(p.due)+'"></td><td><button type="button" class="text-btn red-text" data-rp-remove="'+i+'" '+(lockedIds.has(p.id)?'disabled title="Parcela com recebimento registrado"':'')+'>Excluir</button></td></tr>').join('')+'</tbody></table>';for(let el of document.querySelectorAll('[data-rp-value]'))el.oninput=()=>{try{plan[Number(el.dataset.rpValue)].amount=root.EngefexCurrency.parse(el.value);totals();$('#receivablePlanError').textContent=''}catch(e){plan[Number(el.dataset.rpValue)].amount=NaN;showError(e)}};for(let el of document.querySelectorAll('[data-rp-date]'))el.oninput=()=>plan[Number(el.dataset.rpDate)].due=el.value;for(let el of document.querySelectorAll('[data-rp-remove]'))el.onclick=()=>{if(pending)return;plan.splice(Number(el.dataset.rpRemove),1);paint()};totals()}
$('#receivablePlanGenerate').onclick=()=>{if(pending)return;try{if(lockedIds.size)throw Error('Há parcelas com recebimentos. Ajuste os valores e vencimentos na grade, preservando essas parcelas.');plan=generate(row.amount,Number($('#receivablePlanCount').value),$('#receivablePlanFirst').value);paint()}catch(e){showError(e)}};$('#receivablePlanAdd').onclick=()=>{if(pending)return;if(plan.length>=120)return showError(Error('Limite de 120 parcelas.'));plan.push({id:id(),amount:0,due:plan.at(-1)?.due||D.today()});paint()};$('#receivablePlanSave').onclick=async()=>{if(pending)return;try{if(JSON.stringify(api.getState())!==JSON.stringify(snapshot))throw Error('Os dados mudaram. Feche e reabra o parcelamento.');if(!plan.length)throw Error('Informe ao menos uma parcela.');let next=D.setReceivableInstallments(snapshot,sourceId,type,plan);pending=true;for(let el of document.querySelectorAll('.receivable-plan input,.receivable-plan button'))el.disabled=true;if(await api.save(next)===false)throw Error('O servidor não confirmou o parcelamento. Tente novamente após atualizar.');pending=false;$('#reader').close();api.render();api.toast('Parcelas a receber salvas.')}catch(e){pending=false;showError(e);for(let el of document.querySelectorAll('.receivable-plan input,.receivable-plan button'))el.disabled=false}};paint()}
root.EngefexReceivableInstallments={generate,generateTerms,open,isDirty:()=>!!$('#reader')?.open&&!!$('#readerContent .receivable-plan'),busy:()=>pending,init:bridge=>api=bridge,handle(action){if(!action?.startsWith('receivable-plan:'))return false;try{let [type,sourceId]=JSON.parse(decodeURIComponent(action.slice(16)));open(sourceId,type)}catch(e){api.toast(e.message)}return true}};
})(typeof window==='undefined'?globalThis:window);
